<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/auth.php';require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_admin();$action=$_POST['action']??'';
 try{
  if($action==='save'){
   $id=(int)($_POST['id']??0);$category=(int)($_POST['category_id']??0);$sku=trim($_POST['sku']??'');$name=trim($_POST['name']??'');$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$min=filter_var($_POST['minimum_stock']??null,FILTER_VALIDATE_INT);
   if(!$category||$sku===''||$name===''||$price===false||$price<0||$min===false||$min<0)throw new Exception('Periksa kembali data produk.');
   if($id){$s=$pdo->prepare('UPDATE products SET category_id=?,sku=?,name=?,price=?,minimum_stock=? WHERE id=?');$s->execute([$category,$sku,$name,$price,$min,$id]);}
   else{$s=$pdo->prepare('INSERT INTO products(category_id,sku,name,price,stock,minimum_stock) VALUES(?,?,?,?,0,?)');$s->execute([$category,$sku,$name,$price,$min]);}
   $_SESSION['flash']='Produk berhasil disimpan.';
  }elseif($action==='delete'){$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute([(int)$_POST['id']]);$_SESSION['flash']='Produk berhasil dihapus.';}
 }catch(Throwable $e){$_SESSION['flash']='Produk gagal disimpan/dihapus. Periksa SKU unik, kategori, dan histori transaksi.';}
 header('Location: products.php');exit;
}
$edit=null;if(isset($_GET['edit'])&&is_admin()){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$q=trim($_GET['q']??'');$cat=(int)($_GET['category_id']??0);$sort=$_GET['sort']??'name';$dir=strtoupper($_GET['dir']??'ASC');if(!in_array($sort,['name','sku','price','stock'],true))$sort='name';if(!in_array($dir,['ASC','DESC'],true))$dir='ASC';
$where=[];$params=[];if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ?)';$params[]="%$q%";$params[]="%$q%";}if($cat){$where[]='p.category_id=?';$params[]=$cat;}
$condition=$where?'WHERE '.implode(' AND ',$where):'';$count=$pdo->prepare("SELECT COUNT(*) FROM products p $condition");$count->execute($params);$total=(int)$count->fetchColumn();$perPage=8;$pages=max(1,(int)ceil($total/$perPage));$page=max(1,min($pages,(int)($_GET['page']??1)));$offset=($page-1)*$perPage;
$sql="SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id $condition ORDER BY p.$sort $dir LIMIT $perPage OFFSET $offset";$stmt=$pdo->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$cats=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();
$pageTitle='Produk';include __DIR__.'/includes/header.php';?>
<?php if(is_admin()): ?><section class="panel"><div class="panel-head"><h2><?= $edit?'Edit produk':'Tambah produk' ?></h2><span class="muted">SKU harus unik · Harga dan stok tidak negatif</span></div><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="form-grid"><div class="field"><label>SKU *</label><input name="sku" required maxlength="50" value="<?= h($edit['sku']??'') ?>"></div><div class="field"><label>Nama produk *</label><input name="name" required maxlength="150" value="<?= h($edit['name']??'') ?>"></div><div class="field"><label>Kategori *</label><select name="category_id" required><option value="">Pilih kategori</option><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>" <?= (int)($edit['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Harga (Rp) *</label><input type="number" min="0" step="0.01" name="price" required value="<?= h($edit['price']??'0') ?>"></div><div class="field"><label>Batas minimum stok</label><input type="number" min="0" name="minimum_stock" value="<?= h($edit['minimum_stock']??5) ?>"></div></div><div class="form-actions"><button class="btn">Simpan produk</button><?php if($edit): ?><a class="btn secondary" href="products.php">Batal</a><?php endif; ?></div></form></section><?php endif; ?>
<section class="panel"><div class="panel-head"><div><h2>Daftar Produk</h2><p><?= $total ?> produk terdaftar</p></div></div><div class="toolbar"><form method="get"><input class="search-input" name="q" value="<?= h($q) ?>" placeholder="Cari nama produk atau SKU..."><select class="search-input" name="category_id" style="max-width:190px"><option value="0">Semua kategori</option><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>" <?= $cat===(int)$c['id']?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select><select class="search-input" name="sort" style="max-width:130px"><option value="name">Nama</option><option value="price" <?= $sort==='price'?'selected':'' ?>>Harga</option><option value="stock" <?= $sort==='stock'?'selected':'' ?>>Stok</option><option value="sku" <?= $sort==='sku'?'selected':'' ?>>SKU</option></select><select class="search-input" name="dir" style="max-width:100px"><option>ASC</option><option <?= $dir==='DESC'?'selected':'' ?>>DESC</option></select><button class="btn">Cari</button></form></div><div class="table-wrap"><table><thead><tr><th>PRODUK</th><th>KATEGORI</th><th>HARGA</th><th>STOK</th><th>STATUS</th><?php if(is_admin()): ?><th>AKSI</th><?php endif; ?></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6" class="empty">Tidak ada produk yang cocok.</td></tr><?php else: foreach($rows as $p): ?><tr><td><div class="product-name"><?= h($p['name']) ?></div><div class="muted"><?= h($p['sku']) ?></div></td><td><?= h($p['category_name']) ?></td><td>Rp <?= number_format((float)$p['price'],0,',','.') ?></td><td><b><?= (int)$p['stock'] ?></b><div class="stock-track"><span style="width:<?= min(100,max(4,(int)$p['stock'])) ?>%"></span></div></td><td><span class="badge <?= $p['stock']<=$p['minimum_stock']?'orange':'green' ?>"><?= $p['stock']<=$p['minimum_stock']?'Stok rendah':'Tersedia' ?></span></td><?php if(is_admin()): ?><td><a class="btn secondary small" href="?edit=<?= (int)$p['id'] ?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Hapus produk ini?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="btn danger small">Hapus</button></form></td><?php endif; ?></tr><?php endforeach; endif; ?></tbody></table></div><div class="pagination"><span>Halaman <?= $page ?> dari <?= $pages ?></span><div><?php if($page>1): ?><a href="?<?= http_build_query(array_merge($_GET,['page'=>$page-1])) ?>">← Sebelumnya</a><?php endif; ?><?php if($page<$pages): ?><a href="?<?= http_build_query(array_merge($_GET,['page'=>$page+1])) ?>">Berikutnya →</a><?php endif; ?></div></div></section>
<?php include __DIR__.'/includes/footer.php';?>